#!/usr/bin/env python3
"""Chapter 47, lab 3 (no model): close the evidence gaps the earlier chapters left open and verify the Bulwark release bundle on the real tree.
Adds to the Chapter 35 bundle: C21 (decision-rights register; Chapter 44), C22 (fail-closed edge of the gates; this chapter), C23 (programme checker and case studies; Chapter 45).
Evidence for them: results/ch44_register.json, ch47_malformed_hardened.json + ch47_regress.json, ch45_programmes.json.  Reports the issues verify() finds before and after, per issue kind.
Writes results/ch47_bundle.json.  No model, no network; nothing is signed here."""
import sys, json, time
from collections import Counter
from pathlib import Path
here = Path(__file__).resolve().parent; sys.path.insert(0, str(here))
import ch35_collect as C
from bulwark.bundle import Control, Bundle, make_item, module_digests, verify
SIM = C.SIM
NEW_ITEMS = [
 ("E31", "ch44_register.json", "LAB_SIM", ("ownership",), SIM, "register reconstructed by the author from Chapters 1-43; one organisation; people are composites"),
 ("E32", "ch47_malformed_hardened.json", "LAB_SIM", ("failclosed",), SIM, "68 probes the author thought of; a probe nobody thought of is not covered"),
 ("E33", "ch47_regress.json", "LAB_SIM", ("failclosed",), SIM, "3,000 generated payment requests and 2,000 outputs; generated by the author, not production traffic"),
 ("E34", "ch45_programmes.json", "LAB_SIM", ("casestudy",), SIM, "four programmes described as data by the author; the checker reads the description, not the system"),
 ("E35", "ch47_pytest.log", "UNIT", ("failclosed",), "unit tests, 513 passed", "unit tests run in one process on one machine; they test what the author thought to test"),
]
NEW_CONTROLS = [
 ("C21", "Decision-rights register", "Ian Walsh", ("T03",), "Every decision has a named accountable person, a deputy, a deadline and a timeout rule; a departure of any one named person leaves no decision without an owner in the revised register.", "measured_in_simulation", ("E31",)),
 ("C22", "Fail-closed edge of the gates", "Kevin Brandt", ("T06", "T07"), "A malformed input, an oversized one or a crash inside a gate is refused with a named code; 68 probes, 0 allowed, 0 crashes; no decision changed on 5,000 well-formed cases.", "measured_in_simulation", ("E32", "E33", "E35")),
 ("C23", "Programme check", "Emily Carter", ("T01", "T10"), "A programme described as data is checked for every path from an untrusted source to a dangerous tool that no deterministic gate on a trusted record bounds.", "measured_in_simulation", ("E34",)),
]
MODS = C.MODS + ["ownership", "failclosed", "casestudy"]
def build(ts, items=True, controls=True):
    I = C.ITEMS + (NEW_ITEMS if items else []); K = C.CONTROLS + (NEW_CONTROLS if controls else [])
    its = {i[0]: make_item(here / "results", i[0], i[1], i[2], i[3], i[4], i[5]) for i in I}
    cs = sorted([Control(c[0], c[1], c[2], c[3], c[4], c[5], c[6]) for c in K], key=lambda c: c.id)
    return Bundle("bulwark-0.47", module_digests(here, MODS), cs, its, C.THREATS, ["no production data; every number is from the simulated tenant", "one model for live labs"], ts)
def kinds(iss): return dict(sorted(Counter(k for k, _ in iss).items()))
if __name__ == "__main__":
    now = time.time(); root = here / "results"; res = {}
    b0 = build(now, items=False, controls=False); i0 = verify(b0, root, here, now=now)
    res["before"] = dict(controls=len(b0.controls), items=len(b0.items), issues=kinds(i0)); print("Chapter 35 bundle on today's tree:", res["before"])
    b1 = build(now); i1 = verify(b1, root, here, now=now)
    res["after"] = dict(controls=len(b1.controls), items=len(b1.items), issues=kinds(i1)); print("with C21-C23 and E31-E35:", res["after"])
    for k, d in i1[:10]: print("  ", k, d)
    levels = Counter(c.level for c in b1.controls); res["levels"] = dict(levels); kind = Counter(i.kind for i in b1.items.values()); res["item_kinds"] = dict(kind)
    one = Counter(); [one.update(c.items) for c in b1.controls]
    res["controls_resting_on_one_item"] = sorted(c.id for c in b1.controls if len(c.items) == 1); res["threat_coverage"] = {t: sorted(c.id for c in b1.controls if t in c.threats) for t in C.THREATS}
    res["operating_claims"] = sum(c.level == "operating" for c in b1.controls)
    print("levels:", dict(levels), "| item kinds:", dict(kind), "| controls on one item:", len(res["controls_resting_on_one_item"]), "| operating:", res["operating_claims"])
    json.dump(res, open(root / "ch47_bundle.json", "w"), indent=1, default=list)
